package co.elhacker.maquinitas.servlet;
import co.elhacker.maquinitas.dao.TiendaDAO;import co.elhacker.maquinitas.util.*;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;
@WebServlet("/pedidos") public class PedidosServlet extends HttpServlet {
 private final TiendaDAO dao=new TiendaDAO();
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{Integer u=Autenticacion.usuario(q);if(u==null){Json.enviar(r,401,Map.of("success",false,"message","Inicia sesión."));return;}try{Json.enviar(r,200,Map.of("success",true,"pedidos",Autenticacion.admin(q)?dao.todosPedidos():dao.pedidosUsuario(u)));}catch(Exception e){getServletContext().log("Error pedidos",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudieron consultar los pedidos."));}}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException{Integer u=Autenticacion.usuario(q);if(u==null){Json.enviar(r,401,Map.of("success",false,"message","Inicia sesión."));return;}try{Map body=Json.leerMapa(q);if(Autenticacion.admin(q)){long id=Long.parseLong(String.valueOf(body.get("id_pedido")));dao.cambiarEstadoPedido(id,String.valueOf(body.get("estado")));Json.enviar(r,200,Map.of("success",true,"message","Estado del pedido actualizado."));return;}Object raw=body.get("items");if(!(raw instanceof List))throw new IllegalArgumentException("El carrito no contiene productos.");long id=dao.crearPedido(u,(List<Map<String,Object>>)raw);Json.enviar(r,201,Map.of("success",true,"id_pedido",id,"message","Compra realizada con saldo USDT."));}catch(IllegalArgumentException e){Json.enviar(r,400,Map.of("success",false,"message",e.getMessage()));}catch(Exception e){getServletContext().log("Error creando pedido",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudo procesar el pedido."));}}
}
